package com.adaptiq.dao;
import com.adaptiq.config.DatabaseConnection; import com.adaptiq.exception.DatabaseException; import com.adaptiq.service.AnalyticsSnapshot; import java.sql.*; import java.util.*;
public final class AnalyticsDAO { public AnalyticsSnapshot loadStudent(long id){String q="SELECT COUNT(*),COALESCE(AVG(score),0),COALESCE(MAX(score),0),COALESCE(MIN(score),0),COALESCE(AVG(accuracy),0) FROM exam_attempts WHERE student_id=? AND status IN ('SUBMITTED','EXPIRED')";try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){r.next();return new AnalyticsSnapshot(r.getLong(1),r.getBigDecimal(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getBigDecimal(5),named(c,"SELECT t.topic_name,p.accuracy FROM topic_performance p JOIN topics t ON t.topic_id=p.topic_id WHERE p.student_id=?",id),named(c,"SELECT q.difficulty,COALESCE(AVG(sa.is_correct)*100,0) FROM student_answers sa JOIN exam_attempts a ON a.attempt_id=sa.attempt_id JOIN questions q ON q.question_id=sa.question_id WHERE a.student_id=? AND a.status IN ('SUBMITTED','EXPIRED') GROUP BY q.difficulty",id),trend(c,id));}}catch(SQLException e){throw new DatabaseException("Could not load performance analytics.",e);}}
 private List<AnalyticsSnapshot.NamedAccuracy> named(Connection c,String q,long id)throws SQLException{List<AnalyticsSnapshot.NamedAccuracy>x=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new AnalyticsSnapshot.NamedAccuracy(r.getString(1),r.getBigDecimal(2)));}}return x;} private List<AnalyticsSnapshot.TrendPoint> trend(Connection c,long id)throws SQLException{List<AnalyticsSnapshot.TrendPoint>x=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT DATE_FORMAT(submitted_at,'%d %b'),percentage FROM exam_attempts WHERE student_id=? AND status IN ('SUBMITTED','EXPIRED') ORDER BY submitted_at")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new AnalyticsSnapshot.TrendPoint(r.getString(1),r.getBigDecimal(2)));}}return x;}}
